window.S17Page={"sceneId":"s2","caseId":"s17x-s2-seismic-facies","name":"地震相智能分类","title":"地震相智能分类：从反射纹理认识沉积线索","summary":"振幅相似的地震小窗，为什么会属于不同的反射样式？用原始振幅、空间属性与近邻投票把判断依据展开。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';
 const names=['平行连续相','倾斜反射相','杂乱反射相'];
 function rng(s){return()=>{s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296;};}
 const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;
 function patch(type,seed,noise){const r=rng(seed),phase=r()*6.28,amp=.65+r()*.65,f=.38+r()*.08,slope=type===1?.35+r()*.18:.012;return Array.from({length:24},(_,y)=>Array.from({length:24},(_,x)=>{let shift=type===2?3*Math.sin(x*.9+phase)+2*Math.sin(x*1.9):slope*x;let a=amp*Math.sin(f*(y-shift)+phase);if(type===2)a+=.55*Math.sin(x*1.7+y*.7+phase);return a+(r()-.5)*2*noise;}));}
 function features(a){let flat=a.flat(),energy=Math.sqrt(mean(flat.map(v=>v*v))),dx=[],dy=[],pairs=[];for(let y=1;y<24;y++)for(let x=1;x<24;x++){dx.push(Math.abs(a[y][x]-a[y][x-1]));dy.push(Math.abs(a[y][x]-a[y-1][x]));if(y<23&&x<23)pairs.push((a[y][x+1]-a[y][x-1])*(a[y+1][x]-a[y-1][x]));}return[energy,mean(dx)/(energy+.001),mean(dy)/(energy+.001),mean(pairs)/(energy*energy+.001)];}
 function make(seed,n,noise){return Array.from({length:n},(_,i)=>{let label=i%3,a=patch(label,seed+i*173,noise);return{id:seed+'-'+i,amplitudes:a,x:features(a),label};});}
 function fit(rows){let mu=rows[0].x.map((_,j)=>mean(rows.map(r=>r.x[j]))),sd=mu.map((v,j)=>Math.sqrt(mean(rows.map(r=>(r.x[j]-v)**2)))||1);return{mu,sd,train:rows.map(r=>({x:r.x.map((v,j)=>(v-mu[j])/sd[j]),label:r.label})),centers:names.map((_,k)=>mean(rows.filter(r=>r.label===k).map(r=>r.x[0])))};}
 function predict(model,inputs,k){return inputs.map(x=>{let z=x.map((v,j)=>(v-model.mu[j])/model.sd[j]),near=model.train.map(r=>({label:r.label,d:r.x.reduce((s,v,j)=>s+(v-z[j])**2,0)})).sort((a,b)=>a.d-b.d).slice(0,k),votes=[0,0,0];near.forEach(r=>votes[r.label]++);let label=votes.indexOf(Math.max(...votes));return{label,votes,confidence:votes[label]/k,baseline:model.centers.map(c=>Math.abs(c-x[0])).reduce((best,d,i,a)=>d<a[best]?i:best,0)};});}
 function evaluate(pred,truth){let matrix=names.map(()=>[0,0,0]);pred.forEach((p,i)=>matrix[truth[i]][p]++);return{matrix,accuracy:pred.filter((p,i)=>p===truth[i]).length/truth.length,macroF1:mean(matrix.map((row,k)=>{let tp=row[k],fp=matrix.reduce((s,r)=>s+r[k],0)-tp,fn=row.reduce((s,v)=>s+v,0)-tp;return 2*tp/(2*tp+fp+fn)||0;})),n:truth.length};}
 function run(options){let noise=Number(options.noise),k=Number(options.k),train=make(1201,120,.2),test=make(8101,60,noise),model=fit(train),predictions=predict(model,test.map(r=>r.x),k);return{options:{noise,k},names,train,test,predictions,model: evaluate(predictions.map(p=>p.label),test.map(r=>r.label)),baseline:evaluate(predictions.map(p=>p.baseline),test.map(r=>r.label)),protocol:{train:120,test:60,trainingSeed:1201,testSeed:8101,features:['RMS振幅','横向差异/RMS','纵向差异/RMS','横纵梯度乘积/RMS²'],truthUsedOnlyForEvaluation:true}};}
 g.S17Case={run,predict,fit,features,names};
})(window);

