 r.names.forEach((n,i)=>map+='<rect x="'+(16+i*175)+'" y="295" width="12" height="12" fill="'+colors[i]+'"/><text x="'+(34+i*175)+'" y="307">'+n+'</text>');$('map').innerHTML=svg(map,'可点选的60小窗预测分布',540,335);
