 let xs=r.test.map(x=>x.x[0]),ys=r.test.map(x=>x.x[1]),minX=Math.min(...xs)-.04,maxX=Math.max(...xs)+.04,minY=0,maxY=Math.max(...ys)*1.12,X=v=>60+(v-minX)/(maxX-minX)*430,Y=v=>260-(v-minY)/(maxY-minY)*225;
 let s='<path d="M60 30v230h430" fill="none" stroke="#a0b3a6"/>';for(let i=0;i<=4;i++){let x=minX+(maxX-minX)*i/4,y=maxY*i/4;s+='<text x="'+X(x)+'" y="280" text-anchor="middle">'+x.toFixed(2)+'</text><text x="52" y="'+(Y(y)+4)+'" text-anchor="end">'+y.toFixed(2)+'</text>';}
